server {
    listen 80;
    server_name reports.example.com;
    location / {
        proxy_pass http://127.0.0.1:8000;
        proxy_connect_timeout 5s;
        proxy_read_timeout 120s;
        proxy_send_timeout 60s;
        proxy_set_header Host $host;
    }
}

server {
    listen 80;
    server_name django.example.com;
    location / {
        proxy_pass http://unix:/run/gunicorn/gunicorn.sock;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

location /api/ {
    proxy_pass http://127.0.0.1:9000/;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
}

location /api/ {
    proxy_pass http://127.0.0.1:9000;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
}

location /events {
    proxy_pass http://127.0.0.1:7000;
    proxy_buffering off;
    proxy_http_version 1.1;
    proxy_set_header Connection '';
    proxy_read_timeout 1h;
}

location / {
    proxy_pass https://api.internal.example:8443;
    proxy_ssl_server_name on;
    proxy_ssl_name api.internal.example;
    proxy_ssl_verify on;
    proxy_ssl_trusted_certificate /etc/nginx/ca/internal-ca.pem;
    proxy_set_header Host $host;
}

location /reports {
    proxy_pass http://127.0.0.1:8080;
    proxy_connect_timeout 10s;
    proxy_read_timeout 600s;
    proxy_send_timeout 600s;
}

server {
    listen 80;
    server_name php.example.com;
    root /var/www/php;
    proxy_hide_header X-Powered-By;
    proxy_hide_header Server;
    location / {
        proxy_pass http://127.0.0.1:8081;
        proxy_set_header Host $host;
    }
}

location / {
    proxy_pass http://127.0.0.1:8080;
    proxy_set_header Host $host:$server_port;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
}

location /upload {
    client_max_body_size 50m;
    proxy_pass http://127.0.0.1:9100;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
}

location /hooks/stripe {
    proxy_pass http://127.0.0.1:9300;
    proxy_request_buffering off;
    proxy_set_header Host $host;
    proxy_set_header X-Stripe-Signature $http_stripe_signature;
}

server {
    listen 80;
    server_name console.example.com;
    location / {
        proxy_pass http://127.0.0.1:5173;
        proxy_set_header Host $host;
    }
    location /admin {
        proxy_pass http://127.0.0.1:4000;
        proxy_set_header Host $host;
    }
}

location / {
    proxy_pass http://127.0.0.1:8085;
    proxy_buffer_size 16k;
    proxy_buffers 4 16k;
    proxy_busy_buffers_size 32k;
    proxy_set_header Host $host;
}

location / {
    resolver 10.96.0.10 valid=30s;
    set $backend http://web-frontend.default.svc.cluster.local:8080;
    proxy_pass $backend;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
}

server {
    listen 80;
    server_name shop.example.com;
    location / {
        proxy_pass http://127.0.0.1:3001;
        proxy_intercept_errors on;
        error_page 502 503 504 /upstream-down.html;
    }
    location = /upstream-down.html {
        root /var/www/html;
        internal;
    }
}

server {
    listen 443 ssl;
    http2 on;
    server_name grpc.example.com;
    ssl_certificate /etc/nginx/tls/fullchain.pem;
    ssl_certificate_key /etc/nginx/tls/privkey.pem;
    location / {
        grpc_pass grpc://127.0.0.1:50051;
        grpc_set_header X-Real-IP $remote_addr;
        grpc_read_timeout 300s;
    }
}

location / {
    proxy_pass http://127.0.0.1:8090;
    proxy_socket_keepalive on;
    proxy_set_header Host $host;
}

server {
    listen 443 ssl;
    server_name idp.example.com;
    ssl_certificate /etc/nginx/tls/fullchain.pem;
    ssl_certificate_key /etc/nginx/tls/privkey.pem;
    ssl_client_certificate /etc/nginx/tls/client-ca.pem;
    ssl_verify_client optional;
    location / {
        proxy_pass https://127.0.0.1:8443;
        proxy_ssl_verify on;
        proxy_ssl_trusted_certificate /etc/nginx/tls/backend-ca.pem;
        proxy_set_header X-Client-Cert $ssl_client_cert_dn;
        proxy_set_header X-Client-Verify $ssl_client_verify;
    }
}

location /checkout {
    proxy_pass http://127.0.0.1:9500;
    proxy_next_upstream off;
    proxy_set_header Host $host;
}
